<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
header('Access-Control-Allow-Origin: *');
header('Access-Control-Allow-Headers: Content-Type, Authorization');
header('Access-Control-Allow-Methods: GET, POST, OPTIONS');
if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}
$c=require __DIR__.'/config.php';
function out($a,$s=200){http_response_code($s);echo json_encode($a,JSON_UNESCAPED_UNICODE);exit;}
function body(){return json_decode(file_get_contents('php://input'),true)?:[];}
function db(){global $c;static $p=null;if($p)return $p;if(str_contains($c['db_name'],'YOUR_'))out(['success'=>false,'message'=>'Isi konfigurasi database backend/config.php.'],500);try{$p=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}catch(Throwable $e){out(['success'=>false,'message'=>'Database belum terhubung.'],500);}}
function user(){global $c;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))out(['success'=>false,'message'=>'Login diperlukan.'],401);$a=explode('.',$m[1]);if(count($a)!==2)out(['success'=>false,'message'=>'Sesi tidak valid.'],401);$sig=rtrim(strtr(base64_encode(hash_hmac('sha256',$a[0],$c['app_secret'],true)),'+/','-_'),'=');if(!hash_equals($sig,$a[1]))out(['success'=>false,'message'=>'Sesi tidak valid.'],401);$u=json_decode(base64_decode(strtr($a[0],'-_','+/')),true);if(!$u||$u['exp']<time())out(['success'=>false,'message'=>'Sesi kedaluwarsa.'],401);return $u;}
function token($u){global $c;$p=rtrim(strtr(base64_encode(json_encode(['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role'],'exp'=>time()+604800])),'+/','-_'),'=');return $p.'.'.rtrim(strtr(base64_encode(hash_hmac('sha256',$p,$c['app_secret'],true)),'+/','-_'),'=');}
$a=$_GET['action']??'health';$m=$_SERVER['REQUEST_METHOD'];
if($a==='health')out(['success'=>true,'message'=>'Shinta Shop API aktif']);
if($a==='products'&&$m==='GET')out(['success'=>true,'products'=>db()->query('SELECT id,name,description,price,category,emoji,stock FROM ss2_products WHERE active=1 ORDER BY id DESC')->fetchAll()]);
if($a==='register'&&$m==='POST'){$b=body();$n=trim($b['name']??'');$e=strtolower(trim($b['email']??''));$pw=$b['password']??'';if(strlen($n)<2||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)out(['success'=>false,'message'=>'Isi nama, email valid, password minimal 8 karakter.'],422);try{$s=db()->prepare("INSERT INTO ss2_users(name,email,password_hash,role) VALUES(?,?,?,'customer')");$s->execute([$n,$e,password_hash($pw,PASSWORD_DEFAULT)]);}catch(Throwable $x){out(['success'=>false,'message'=>'Email sudah terdaftar atau data tidak valid.'],409);}$u=['id'=>db()->lastInsertId(),'name'=>$n,'email'=>$e,'role'=>'customer'];out(['success'=>true,'user'=>$u+['token'=>token($u)]],201);}
if($a==='login'&&$m==='POST'){$b=body();$s=db()->prepare('SELECT id,name,email,password_hash,role FROM ss2_users WHERE email=?');$s->execute([strtolower(trim($b['email']??''))]);$u=$s->fetch();if(!$u||!password_verify($b['password']??'',$u['password_hash']))out(['success'=>false,'message'=>'Email atau password salah.'],401);unset($u['password_hash']);$u['id']=(int)$u['id'];out(['success'=>true,'user'=>$u+['token'=>token($u)]]);}
if($a==='orders'&&$m==='GET'){$u=user();$s=db()->prepare('SELECT id,total,status,created_at FROM ss2_orders WHERE user_id=? ORDER BY id DESC');$s->execute([$u['id']]);out(['success'=>true,'orders'=>$s->fetchAll()]);}
if($a==='orders/create'&&$m==='POST'){$u=user();$items=body()['items']??[];if(!is_array($items)||!$items)out(['success'=>false,'message'=>'Keranjang kosong.'],422);$p=db();$p->beginTransaction();try{$total=0;$valid=[];foreach($items as $it){$id=(int)($it['product_id']??0);$q=(int)($it['quantity']??0);$s=$p->prepare('SELECT * FROM ss2_products WHERE id=? FOR UPDATE');$s->execute([$id]);$pr=$s->fetch();if(!$pr||!$pr['active']||$q<1||$q>99||$pr['stock']<$q)throw new Exception('Produk tidak tersedia atau stok tidak cukup.');$total+=$pr['price']*$q;$valid[]=[$pr,$q];}$s=$p->prepare("INSERT INTO ss2_orders(user_id,total,status) VALUES(?,?,'pending')");$s->execute([$u['id'],$total]);$oid=$p->lastInsertId();foreach($valid as [$pr,$q]){$s=$p->prepare('INSERT INTO ss2_order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)');$s->execute([$oid,$pr['id'],$pr['id']?$pr['name']:'',$q,$pr['price']]);$s=$p->prepare('UPDATE ss2_products SET stock=stock-? WHERE id=?');$s->execute([$q,$pr['id']]);}$p->commit();out(['success'=>true,'order_id'=>$oid,'total'=>$total]);}catch(Throwable $e){$p->rollBack();out(['success'=>false,'message'=>$e->getMessage()],422);}}
if(str_starts_with($a,'admin/')){$u=user();if($u['role']!=='admin')out(['success'=>false,'message'=>'Khusus admin.'],403);if($a==='admin/orders'&&$m==='GET')out(['success'=>true,'orders'=>db()->query('SELECT o.id,o.total,o.status,o.created_at,u.name customer_name FROM ss2_orders o JOIN ss2_users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll()]);if($a==='admin/order-status'&&$m==='POST'){$b=body();if(!in_array($b['status']??'', ['pending','processing','ready','completed','cancelled'],true))out(['success'=>false,'message'=>'Status tidak valid.'],422);$s=db()->prepare('UPDATE ss2_orders SET status=? WHERE id=?');$s->execute([$b['status'],(int)$b['order_id']]);out(['success'=>true]);}}
out(['success'=>false,'message'=>'Endpoint tidak ditemukan.'],404);
